// Writes <dir>/_generated/{dataModel,server,api}.ts.
// Types are inferred from your files, so this only needs the list of modules.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { listSourceFiles, modulePathFor } from "./project";

const HEADER = `/* eslint-disable */
// Generated by onebase. Do not edit: run \`onebase codegen\` (or \`onebase dev\`) instead.
`;

type Tree = { [segment: string]: Tree | string };

function renderTree(tree: Tree, visibility: string, indent: string): string {
  const lines = Object.entries(tree).map(([key, value]) => {
    const k = /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : JSON.stringify(key);
    if (typeof value === "string") return `${indent}  ${k}: ApiFromModule<typeof ${value}, "${visibility}">;`;
    return `${indent}  ${k}: ${renderTree(value, visibility, indent + "  ")};`;
  });
  return `{\n${lines.join("\n")}\n${indent}}`;
}

export async function generateFiles(dirInput: string): Promise<Record<string, string>> {
  const dir = resolve(dirInput);
  const files = await listSourceFiles(dir);
  const modulePaths = files.map((f) => modulePathFor(dir, f));
  const hasSchema = modulePaths.includes("schema");
  const fnModules = modulePaths.filter((m) => m !== "schema" && m !== "auth.config");

  const dataModel = `${HEADER}
import type { ${hasSchema ? "DataModelFromSchema, " : ""}GenericId } from "onebase/server";
${hasSchema ? `import type schema from "../schema";\n\nexport type DataModel = DataModelFromSchema<typeof schema>;` : `\n/** No schema.ts yet: every table accepts any document. */\nexport type DataModel = Record<string, { document: any; indexes: Record<string, string[]> }>;`}
export type TableNames = keyof DataModel & string;
/** A document from \`table\`, including _id and _creationTime. */
export type Doc<T extends TableNames> = DataModel[T]["document"];
/** The id of a document in \`table\`, or of a stored file (\`Id<"_storage">\`). */
export type Id<T extends TableNames | "_storage"> = GenericId<T>;
`;

  const serverFile = `${HEADER}
import {
  makeServer,
  type ActionCtx as GenericActionCtx,
  type DatabaseReader as GenericDatabaseReader,
  type DatabaseWriter as GenericDatabaseWriter,
  type MutationCtx as GenericMutationCtx,
  type QueryCtx as GenericQueryCtx,
} from "onebase/server";
import type { DataModel } from "./dataModel";

export const { query, mutation, action, internalQuery, internalMutation, internalAction, httpAction } =
  makeServer<DataModel>();

export type QueryCtx = GenericQueryCtx<DataModel>;
export type MutationCtx = GenericMutationCtx<DataModel>;
export type ActionCtx = GenericActionCtx<DataModel>;
export type DatabaseReader = GenericDatabaseReader<DataModel>;
export type DatabaseWriter = GenericDatabaseWriter<DataModel>;
`;

  const tree: Tree = {};
  const imports: string[] = [];
  fnModules.forEach((modulePath, i) => {
    const alias = `module${i}`;
    imports.push(`import type * as ${alias} from "../${modulePath}";`);
    const segments = modulePath.split("/");
    let node = tree;
    for (const seg of segments.slice(0, -1)) node = (node[seg] ??= {}) as Tree;
    node[segments[segments.length - 1]!] = alias;
  });
  const apiFile = `${HEADER}
import { anyApi, type ApiFromModule } from "onebase/server";
${imports.join("\n")}

/** References to public functions, e.g. \`api.messages.list\`. */
export const api: ${renderTree(tree, "public", "")} = anyApi;

/** References to internal functions (callable from other functions only). */
export const internal: ${renderTree(tree, "internal", "")} = anyApi;
`;

  return {
    [join(dir, "_generated", "dataModel.ts")]: dataModel,
    [join(dir, "_generated", "server.ts")]: serverFile,
    [join(dir, "_generated", "api.ts")]: apiFile,
  };
}

/** Writes generated files; returns the ones that changed. */
export async function codegen(dir: string): Promise<string[]> {
  const files = await generateFiles(dir);
  mkdirSync(join(resolve(dir), "_generated"), { recursive: true });
  const changed: string[] = [];
  for (const [path, content] of Object.entries(files)) {
    if (existsSync(path) && readFileSync(path, "utf8") === content) continue;
    writeFileSync(path, content);
    changed.push(path);
  }
  return changed;
}

export async function staleGeneratedFiles(dir: string): Promise<string[]> {
  const files = await generateFiles(dir);
  return Object.entries(files)
    .filter(([path, content]) => !existsSync(path) || readFileSync(path, "utf8") !== content)
    .map(([path]) => path);
}
